fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Sanity checks (can be omitted if you assume valid inputs according to the problem statement)
    assert_eq!(
        a.len(),
        mask.len(),
        "Input array and mask must have the same length"
    );
    assert!(
        !values.is_empty(),
        "Replacement values array must not be empty"
    );

    let val_len = values.len();

    a.into_iter()
        .zip(mask.into_iter())
        .enumerate()
        .map(|(i, (ai, use_replacement))| {
            if use_replacement {
                // pick from `values` using wrap‐around indexing
                values[i % val_len]
            } else {
                ai
            }
        })
        .collect()
}